import { atom, read, update } from 'claude-code'
import type { EngineInterface, FsEntry, Register, TurnUsage } from 'claude-code'

import type { JobRecord, OfficeEvent, PeerSession, PeerStatus, Usage } from '../types'
import { debugOn, logText, note, takeDirty } from './debuglog'
import { MAIN, emptyScene, needsSweep, reduceAt, restore } from './model'
import { registerPane } from './pane'
import {
  BEAT_MS,
  CALM_MS,
  PEER_FILE_MAX,
  POLL_MS,
  STALE_MS,
  baseName,
  contentOf,
  freeSlots,
  isTakenFrom,
  livePeers,
  lookedOf,
  parsePeer,
  peerKey,
  peerDirOf,
  peerStatusOf,
  shownOf,
  slotName,
  slotOf,
  snapshotOf,
  tombstoneOf,
  urgentOf,
} from './peers'
import type { Self, SlotSeen } from './peers'
import { HISTORY_MAX, SESSION_MAX, isRecord, jobRecord, recapOf, withRecord } from './recap'
import { LEAD_MS, nowOf } from './render'
import { CANNOT, MANY_COPIES, SETTINGS_HELP, USAGE, configKeyOf, parseSet, replyAfterSet, setReply, settingLines } from './settings'
import type { Setting } from './settings'
import { PANE, PANE_TITLE, PROBE_BOTTOM, PROBE_TOP } from './state'
import { WAITING_TOOLS, detailOf, fullText, gist, stationFor, targetOf, todoCounts } from './stations'

export const FLUSH_MS = 350
// How much of a helper's brief and of its report the office keeps, to be read in full from its details box.
export const TEXT_MAX = 2000
// How much of your message names the job in its recap.
export const TASK_MAX = 120
const SWEEP_EVERY = 15
const CLOCK_EVERY = 3
const QUEUE_MAX = 500
// With reminders on: how long an agent waits on you before the office says so, once per wait.
export const REMIND_AFTER_MS = 30_000
export const REMIND_TITLE = 'Pixel Office'
// The debug log is written at most this often.
const DEBUG_WRITE_MS = 1000

// The history, when it is switched on, lives under one key of the mod's store.
export const HISTORY_KEY = 'jobs'
const UNTRACKED = new Set(['Agent', 'Task'])
// These wake Main about work already under way, so they continue the job; a scheduled trigger, the composer,
// the bridge and the SDK are a person's or a host's own new message.
const NOT_A_NEW_JOB = new Set(['task-notification', 'peer', 'peer-send-message'])

// Atoms cannot be imported across files, so each file that reads one declares it again; pane.tsx has the same three.
const sceneAtom = atom({ plugin: 'pixel-office', key: 'scene' } as const, emptyScene())
const selectedAtom = atom({ plugin: 'pixel-office', key: 'selected' } as const, null as string | null)
const clockAtom = atom({ plugin: 'pixel-office', key: 'clock' } as const, 0)
const expandedAtom = atom({ plugin: 'pixel-office', key: 'expanded' } as const, null as 'brief' | 'report' | null)
const jobOpenAtom = atom({ plugin: 'pixel-office', key: 'jobOpen' } as const, false)
const historyAtom = atom({ plugin: 'pixel-office', key: 'history' } as const, [] as JobRecord[])
const sessionAtom = atom({ plugin: 'pixel-office', key: 'session' } as const, [] as JobRecord[])
const othersAtom = atom({ plugin: 'pixel-office', key: 'others' } as const, [] as PeerSession[])
const lookingAtom = atom({ plugin: 'pixel-office', key: 'looking' } as const, null as string | null)
const lookedAtom = atom({ plugin: 'pixel-office', key: 'looked' } as const, null as PeerSession | null)


// A turn's token counts, summed over its requests (absent when nothing counted: an interrupt, an API error).
const usageOf = (u: TurnUsage | undefined): Usage | null =>
  u === undefined
    ? null
    : {
        tokens: u.input_tokens + u.output_tokens + u.cache_read_input_tokens + u.cache_creation_input_tokens,
        reused: u.cache_read_input_tokens,
        model: u.model,
      }

const quietly = async (work: () => Promise<void> | void): Promise<void> => {
  try {
    await work()
  } catch {
    // The office is best effort: it never disturbs the session it watches.
  }
}

// The other sessions on this computer (option `otherSessions`), looked at on a schedule of its own beside the flush,
// so a slow or stuck disk never holds up this session's own office.
type Peers = {
  // The shared folder: undefined until looked up, null when there is none.
  dir: string | null | undefined
  // This load of the module: a hot reload or a second process on the same session is another instance.
  instance: string
  startedAt: number
  slot: number | null
  hasClaimed: boolean
  // When the slot was last read back holding this instance (or claimed): the tombstone is written only then.
  verifiedAt: number
  lastPoll: number
  lastBeat: number
  lastContent: string
  status: PeerStatus | null
  since: number
  isBusy: boolean
  // Counts the looks. A look that overran LOOK_MAX_MS is let go: the next one starts, and the old one, if its disk
  // call ever comes back, finds the count moved on and changes nothing.
  looks: number
  // The file a look is reading now, and the files a look was let go on: those are left alone from then on, as
  // odd slots are, so one file that never answers cannot stop every later look.
  reading: string | null
  stuck: Set<string>
  isEnded: boolean
  run: Promise<void> | null
  // Each slot file last read as a snapshot, by name, with the size and time it had then. A file that did not
  // parse is never kept, so it is read again next time.
  cache: Map<string, { mtimeMs: number; size: number; readAt: number; peer: PeerSession }>
  urgent: string
  shown: string
  shownAt: number
  reminded: Set<string>
}

// `epoch` counts the /clears: a flush notes it when it takes the queue, so it can tell its batch has gone stale.
type Office = {
  queue: OfficeEvent[]
  isFlushing: boolean
  flushes: number
  isOpened: boolean
  wantsOpen: boolean
  epoch: number
  keepsHistory: boolean
  hasJobToSave: boolean
  reminds: boolean
  // When each agent now waiting on you started to, and which of them were reminded about this wait.
  waitingSince: Map<string, number>
  reminded: Set<string>
  // The opt-in debug log: whether it is on, and when it was last written.
  isDebug: boolean
  lastDebugWrite: number
  // Where the latest prompt came from (its origin kind); the turn it starts reads and clears it.
  lastOrigin: string | null
  // Null while `otherSessions` is off: then nothing is written or read.
  peers: Peers | null
}

// The engine only lets `$` travel into functions declared at the top of this file, so the helpers that
// take it live here and share the mutable bits through one plain object.
async function openPane($: EngineInterface, office: Office): Promise<void> {
  await $.ui.open({ id: PANE, title: PANE_TITLE })
  office.isOpened = true
}

async function loadHistory($: EngineInterface): Promise<void> {
  const saved = await $.store.get(HISTORY_KEY)
  const list = Array.isArray(saved) ? saved.filter(isRecord).slice(-HISTORY_MAX) : []
  await update($, historyAtom, () => list)
}

async function saveJob($: EngineInterface): Promise<void> {
  const recap = recapOf(restore(await read($, sceneAtom)), await $.clock.now())
  if (recap === null) return
  const list = withRecord(await read($, historyAtom), jobRecord(recap))
  await $.store.set(HISTORY_KEY, list)
  await update($, historyAtom, () => list)
}

// The session total is kept in memory whatever the history option says.
async function recordJob($: EngineInterface): Promise<void> {
  const recap = recapOf(restore(await read($, sceneAtom)), await $.clock.now())
  if (recap === null) return
  await update($, sessionAtom, list => withRecord(list, jobRecord(recap), SESSION_MAX))
}

// An agent that has waited on you for a while is said once: a toast, which shows over the transcript wherever the
// session is drawn, and a native notification, which the person's channel raises in a terminal (in the desktop
// app only their own notification hooks run). A wait that ends and begins again is a new wait.
async function remind($: EngineInterface, office: Office): Promise<void> {
  const scene = restore(await read($, sceneAtom))
  const now = await $.clock.now()
  const waiting = Object.values(scene.agents).filter(a => a.phase === 'waiting')
  for (const id of [...office.waitingSince.keys()]) {
    if (waiting.some(a => a.id === id)) continue
    office.waitingSince.delete(id)
    office.reminded.delete(id)
  }
  for (const agent of waiting) {
    const since = office.waitingSince.get(agent.id) ?? now
    office.waitingSince.set(agent.id, since)
    if (now - since < REMIND_AFTER_MS || office.reminded.has(agent.id)) continue
    office.reminded.add(agent.id)
    const text = `${agent.label} is ${nowOf(scene, agent)}`
    $.ui.toast(text, { timeoutMs: 10_000 })
    await $.ui.notify(text, { title: REMIND_TITLE })
  }
}

async function flush($: EngineInterface, office: Office): Promise<void> {
  if (office.isFlushing) return
  office.isFlushing = true
  await quietly(async () => {
    office.flushes += 1
    const now = await $.clock.now()
    const batch = office.queue
    const epoch = office.epoch
    const began = office.isDebug ? now : 0
    office.queue = []
    const isSweepTurn = office.flushes % SWEEP_EVERY === 0
    // Saved from the batch being applied, so the record never misses the end of the turn it is about.
    if (batch.some(ev => ev.kind === 'turnEnded')) office.hasJobToSave = true
    if (batch.length === 0 && !(isSweepTurn && needsSweep(restore(await read($, sceneAtom)), now))) return
    // The pane draws the picture as of LEAD_MS ahead, right after this write: the walks these events start begin
    // there, so the picture shows each one from its first step.
    const shownAt = now + LEAD_MS
    await update($, sceneAtom, scene => {
      // A /clear since the queue was taken makes this batch (and sweep) belong to the old conversation. The
      // updater reruns when a write misses its version, so the check holds however the two interleave.
      if (office.epoch !== epoch) return scene
      const applied = batch.reduce((s, ev) => reduceAt(s, ev, shownAt), restore(scene))
      return isSweepTurn && needsSweep(applied, now) ? reduceAt(applied, { kind: 'tick', at: now }, shownAt) : applied
    })
    if (office.isDebug) note('flush', { batch: batch.length, ms: (await $.clock.now()) - began }, now)
  })
  // The "On the job" clock of a selected agent is the one thing that changes with no event behind it:
  // about once a second, while a row is open, write the time to state. The pane reads that atom, and a state
  // write is what makes the desktop pane redraw (a bare redraw request from this timer does not).
  // Only a helper still on the job has a clock to keep: not Main, not one that has left, not a pruned id.
  // The open recap of a job still running keeps time the same way.
  await quietly(async () => {
    if (office.flushes % CLOCK_EVERY !== 0) return
    const scene = restore(await read($, sceneAtom))
    const selected = await read($, selectedAtom)
    const agent = selected === null || selected === MAIN ? undefined : scene.agents[selected]
    const isClockShown = agent !== undefined && agent.phase !== 'gone'
    const isJobShown = (await read($, jobOpenAtom)) && scene.job !== null && scene.job.endedAt === null
    if (!isClockShown && !isJobShown) return
    const now = await $.clock.now()
    await update($, clockAtom, () => now)
  })
  // The history is written after the scene, so the record holds the turn that just ended.
  const isJobDue = office.hasJobToSave
  office.hasJobToSave = false
  await quietly(async () => {
    if (isJobDue) await recordJob($)
  })
  await quietly(async () => {
    if (office.keepsHistory && isJobDue) await saveJob($)
  })
  await quietly(async () => {
    if (office.reminds && office.flushes % CLOCK_EVERY === 0) await remind($, office)
  })
  // The debug log is a file the maintainer can read: rewritten as a whole, when it has changed, at most once a second.
  await quietly(async () => {
     if (!office.isDebug || !takeDirty()) return
    const at = await $.clock.now()
    if (at - office.lastDebugWrite < DEBUG_WRITE_MS) return
    office.lastDebugWrite = at
    await $.fs.write(`${$.plugin.root}/debug/log.jsonl`, logText())
  })
  // The session and spawn hooks only ask for the pane; it opens here, off their path, and a failed open tries again next flush.
  await quietly(async () => {
    if (office.wantsOpen && !office.isOpened) await openPane($, office)
  })
  office.isFlushing = false
}

// Whether `every` has passed since `at`. A clock set back makes it due at once, so the beat goes on rather than
// stopping until the clock catches up again.
// A look that takes longer than this is let go; each wait at the end of a session is shorter still.
const LOOK_MAX_MS = 5000
const END_WAIT_MS = 300
const MTIME_SLACK_MS = 2000

const isDue = (now: number, at: number, every: number): boolean => now < at || now - at >= every

async function peerDir($: EngineInterface): Promise<string | null> {
  const configDir = await $.env.get('CLAUDE_CONFIG_DIR')
  const home = await $.env.get('HOME')
  const userProfile = await $.env.get('USERPROFILE')
  return peerDirOf({ configDir, home, userProfile })
}

// Reads the slots that changed since they were last read. A slot that is not a plain small file (a link, a folder,
// something big) is marked odd: never read, never written to, never free. Null when the folder is there but cannot
// be listed: every slot would look free, and this copy must not write into one another holds.
async function readSlots($: EngineInterface, peers: Peers, dir: string, now: number): Promise<Map<number, SlotSeen> | null> {
  const seen = new Map<number, SlotSeen>()
  const listed: FsEntry[] | null = await $.fs.list(dir).catch(() => null)
  if (listed === null && (await $.fs.exists(dir).catch(() => true))) return null
  const entries = listed ?? []
  for (const entry of entries) {
    const slot = slotOf(entry.name)
    if (slot === null) continue
    if (entry.kind !== 'file' || entry.isLink || entry.size > PEER_FILE_MAX || peers.stuck.has(entry.name)) {
      seen.set(slot, { peer: null, mtimeMs: entry.mtimeMs, isOdd: true })
      continue
    }
    // This copy's own slot is always read afresh: it is how a copy learns another took it. So is a file read within
    // MTIME_SLACK_MS of its last change: a rewrite of the same size in the same tick of a coarse file clock (FAT,
    // a network share) would keep its time, and the change would go unseen.
    const cached = peers.cache.get(entry.name)
    const isSettled = cached !== undefined && cached.readAt - cached.mtimeMs > MTIME_SLACK_MS
    if (slot !== peers.slot && isSettled && cached.mtimeMs === entry.mtimeMs && cached.size === entry.size) {
      seen.set(slot, { peer: cached.peer, mtimeMs: entry.mtimeMs, isOdd: false })
      continue
    }
    peers.reading = entry.name
    const text: unknown = await $.fs.read(`${dir}/${entry.name}`).catch(() => null)
    peers.reading = null
    const peer = typeof text === 'string' ? parsePeer(text) : null
    // A file caught half written keeps its last good copy, which ages out as any other, and stays uncached so the
    // next look reads it again; a session does not drop out of the list for one bad read.
    if (peer !== null) peers.cache.set(entry.name, { mtimeMs: entry.mtimeMs, size: entry.size, readAt: now, peer })
    seen.set(slot, { peer: peer ?? cached?.peer ?? null, mtimeMs: entry.mtimeMs, isOdd: false })
  }
  return seen
}

// One look at the other sessions, at most every POLL_MS: read the slots, keep (or claim) this copy's own, write its
// snapshot when it changed or a heartbeat is due, and hand the pane the others when what it shows has changed.
async function lookAround($: EngineInterface, office: Office, peers: Peers, look: number): Promise<void> {
  const now = await $.clock.now()
  if (!isDue(now, peers.lastPoll, POLL_MS)) return
  peers.lastPoll = now
  if (peers.startedAt === 0) peers.startedAt = now
  if (peers.dir === undefined) peers.dir = await peerDir($)
  const dir = peers.dir
  if (dir === null) return
  // Read every time: a /clear goes on under a new session id.
  const sessionId = await $.session.id()
  const self = { instance: peers.instance, sessionId }
  const seen = await readSlots($, peers, dir, now)
  if (seen === null || look !== peers.looks) return

  // Two copies that took one slot at once: the one that sees the other's snapshot there moves.
  const mine = peers.slot === null ? undefined : seen.get(peers.slot)
  if (peers.slot !== null && (mine?.isOdd === true || isTakenFrom(mine, peers.instance, now))) {
    peers.slot = null
    peers.lastContent = ''
  }
  if (peers.slot === null) {
    const { own, free } = freeSlots(seen, self, now)
    // Only a first claim takes back this session's slot from an older copy (a hot reload's): a copy that was moved
    // on must not take it back from the copy that moved it, or two processes on one session would swap for ever.
    const chosen = !peers.hasClaimed && own !== null ? own : free.length === 0 ? null : free[Math.floor(Math.random() * free.length)] ?? null
    peers.slot = chosen
    if (chosen !== null) {
      peers.hasClaimed = true
      peers.verifiedAt = now
      peers.lastContent = ''
    }
  } else {
    peers.verifiedAt = now
    // Anything but this copy's own snapshot in its slot (a stale one, a broken one) is put right at once.
    if (mine?.peer?.instance !== peers.instance) peers.lastContent = ''
  }

  const scene = restore(await read($, sceneAtom))
  const status = peerStatusOf(scene)
  if (status !== peers.status) {
    peers.status = status
    peers.since = now
  }
  if (peers.slot !== null) {
    const project = baseName(await $.session.root())
    const snapshot = snapshotOf(scene, { instance: peers.instance, sessionId, startedAt: peers.startedAt, project, since: peers.since }, now)
    const content = contentOf(snapshot)
    // Checked last thing before the write: once the session has ended its tombstone must be the slot's last word.
    if ((content !== peers.lastContent || isDue(now, peers.lastBeat, BEAT_MS)) && !peers.isEnded && look === peers.looks) {
      await $.fs.write(`${dir}/${slotName(peers.slot)}`, JSON.stringify(snapshot))
      peers.lastContent = content
      peers.lastBeat = now
    }
  }

  const others = livePeersOf(seen, self, now)
  const urgent = urgentOf(others)
  const shown = shownOf(others)
  if (look !== peers.looks) return
  if (urgent !== peers.urgent || (shown !== peers.shown && isDue(now, peers.shownAt, CALM_MS))) {
    peers.urgent = urgent
    peers.shown = shown
    peers.shownAt = now
    await update($, othersAtom, () => others)
  }

  // The office being looked in on is redrawn as soon as what it shows changes, without the list's calm window: while
  // it is on show, this session's own walks are not, so its redraws restart nothing anyone is watching. A session
  // that has gone takes the picture back to this office.
  const looking = await read($, lookingAtom)
  const shownNow = await read($, lookedAtom)
  if (look !== peers.looks) return
  const found = looking === null ? undefined : others.find(p => peerKey(p) === looking)
  // A press between the read above and these writes wins: each write checks the pane still looks where it did.
  if (looking !== null && found === undefined) {
    await update($, lookingAtom, current => (current === looking ? null : current))
    if ((await read($, lookingAtom)) === null) await update($, lookedAtom, () => null)
  } else if (found !== undefined && (shownNow === null || lookedOf(found) !== lookedOf(shownNow))) {
    if ((await read($, lookingAtom)) === looking) await update($, lookedAtom, () => found)
  }

  // With reminders on, another session waiting on you for a while is said once, as a toast only: that session
  // raises its own notification, and one from every other session would repeat it.
  if (office.reminds) {
    const waits = new Set(others.filter(p => p.status === 'waiting').map(p => `${p.sessionId}:${p.instance}:${p.since}`))
    for (const key of [...peers.reminded]) if (!waits.has(key)) peers.reminded.delete(key)
    for (const peer of others) {
      const key = `${peer.sessionId}:${peer.instance}:${peer.since}`
      if (peer.status !== 'waiting' || now - peer.since < REMIND_AFTER_MS || peers.reminded.has(key)) continue
      peers.reminded.add(key)
      $.ui.toast(`In ${peer.project === '' ? 'another session' : peer.project}, an agent is waiting on you`, { timeoutMs: 10_000 })
    }
  }
}

const livePeersOf = (seen: ReadonlyMap<number, SlotSeen>, self: Self, now: number): PeerSession[] =>
  livePeers(
    [...seen.values()].flatMap(found => (found.peer === null ? [] : [found.peer])),
    self,
    now,
  )

function peerTick($: EngineInterface, office: Office): void {
  const peers = office.peers
  if (peers === null || peers.isBusy || peers.isEnded) return
  peers.isBusy = true
  peers.looks += 1
  const look = peers.looks
  const ran = quietly(() => lookAround($, office, peers, look))
  peers.run = Promise.race([ran, quietly(() => $.clock.sleep(LOOK_MAX_MS))]).finally(() => {
    if (peers.looks !== look) return
    peers.isBusy = false
    // Let go: whatever the overrun look does when it comes back, it changes nothing.
    peers.looks += 1
    if (peers.reading !== null) peers.stuck.add(peers.reading)
    peers.reading = null
  })
}

// The session is over (not a /clear or a resume, which go on under a new id): mark the slot free for the others.
// One write, after any look already under way, and only into a slot this copy recently saw as its own, as the whole
// end of a session has a short bound and another copy may have taken a slot this one lost track of.
async function endPeers($: EngineInterface, office: Office): Promise<void> {
  const peers = office.peers
  if (peers === null || peers.isEnded) return
  peers.isEnded = true
  // Each wait is short, as the whole end of a session has a bound of its own and a stuck disk must not use it up.
  if (peers.run !== null) await Promise.race([peers.run, quietly(() => $.clock.sleep(END_WAIT_MS))])
  if (peers.slot === null || typeof peers.dir !== 'string') return
  const now = await $.clock.now()
  if (Math.abs(now - peers.verifiedAt) > STALE_MS) return
  // Only over this copy's own snapshot: another copy may have taken the slot since the last look.
  const path = `${peers.dir}/${slotName(peers.slot)}`
  const text: unknown = await Promise.race([$.fs.read(path).catch(() => null), quietly(() => $.clock.sleep(END_WAIT_MS)).then(() => null)])
  const held = typeof text === 'string' ? parsePeer(text) : null
  if (held?.instance !== peers.instance) return
  const meta = { instance: peers.instance, sessionId: await $.session.id(), startedAt: peers.startedAt, project: '', since: now }
  await $.fs.write(path, JSON.stringify(tombstoneOf(meta, now)))
}

// Changes one setting the way the `/config` menu does, and says how it went. pane.tsx and register.tsx each have
// this: the engine follows `$` only into a function of the same file.
async function changeSetting($: EngineInterface, setting: Setting, value: string): Promise<string> {
  let keys: string[] = []
  try {
    keys = (await $.config.list()).map(row => row.key)
  } catch {
    // An engine without the listing: the key is the plain one.
  }
  const key = configKeyOf(keys, setting.field)
  if (key === null) return setReply(setting, value, MANY_COPIES)
  let deny: string | undefined
  try {
    deny = (await $.config.set({ key, value })).deny
  } catch {
    return setReply(setting, value, CANNOT)
  }
  let stored: unknown
  try {
    stored = (await $.config.list()).find(row => row.key === key)?.value
  } catch {
    // Not listed: the change is taken at its word.
  }
  return replyAfterSet(setting, value, deny, stored)
}

export const register: Register = (on, options) => {
  const autoOpen = String(options.autoOpen ?? 'on-first-subagent')
  const office: Office = {
    queue: [],
    isFlushing: false,
    flushes: 0,
    isOpened: false,
    wantsOpen: false,
    epoch: 0,
    keepsHistory: String(options.history ?? 'off') === 'last-20',
    hasJobToSave: false,
    reminds: String(options.notify ?? 'off') === 'after-30s',
    waitingSince: new Map(),
    reminded: new Set(),
    isDebug: String(options.debug ?? 'off') === 'on',
    lastDebugWrite: 0,
    lastOrigin: null,
    peers:
      String(options.otherSessions ?? 'off') === 'on'
        ? {
            dir: undefined,
            instance: crypto.randomUUID(),
            startedAt: 0,
            slot: null,
            hasClaimed: false,
            verifiedAt: 0,
            lastPoll: 0,
            lastBeat: 0,
            lastContent: '',
            status: null,
            since: 0,
            isBusy: false,
            looks: 0,
            reading: null,
            stuck: new Set(),
            isEnded: false,
            run: null,
            cache: new Map(),
            urgent: '[]',
            shown: '[]',
            shownAt: 0,
            reminded: new Set(),
          }
        : null,
  }
  debugOn(office.isDebug)

  const push = (ev: OfficeEvent): void => {
    if (office.isDebug) {
      const r = ev as Record<string, unknown>
      const agent = typeof r.agentId === 'string' ? r.agentId : typeof r.id === 'string' ? r.id : null
      note('event', { ev: ev.kind, agent, tool: ev.kind === 'toolStarted' ? ev.tool : undefined }, ev.at)
    }
    office.queue.push(ev)
    if (office.queue.length > QUEUE_MAX) office.queue = office.queue.slice(-QUEUE_MAX)
  }

  on('session.start', async ($, e, next) => {
    // Each step stands alone: one that fails must not keep the others from running.
    await quietly(() => {
      $.clock.every(FLUSH_MS, () => {
        void flush($, office)
        peerTick($, office)
      })
    })
    await quietly(async () => {
      await $.command.register({ name: 'office', description: 'Show or hide the pixel office; /office settings lists its settings' })
    })
    await quietly(async () => {
      if (office.keepsHistory) await loadHistory($)
    })
    // The session start hook only asks for the pane, as the spawn hook does; the flush opens it.
    if (autoOpen === 'session-start') office.wantsOpen = true
    return next(e)
  }).catch(($, e, next) => next(e))

  on('session.end', async ($, e, next) => {
    // A /clear ends the conversation but not the process, and no session.start follows it: the office starts
    // over, and the flush timer keeps running. Events still queued belong to the old conversation, and so does
    // a batch a flush has already taken off the queue: bumping the epoch makes that flush leave the new scene alone.
    if (e.reason !== 'clear' && e.reason !== 'resume') await quietly(() => endPeers($, office))
    if (e.reason === 'clear') {
      await quietly(() => {
        office.epoch += 1
        office.queue = []
      })
      await quietly(async () => {
        await update($, sceneAtom, () => emptyScene())
      })
      await quietly(async () => {
        await update($, selectedAtom, () => null)
      })
      await quietly(async () => {
        await update($, expandedAtom, () => null)
      })
      await quietly(async () => {
        await update($, sessionAtom, () => [])
      })
    }
    return next(e)
  }).catch(($, e, next) => next(e))

  on('tool.call', async ($, e, next) => {
    const tool = String(e.tool)
    const agentId = e.agentId ?? MAIN
    const callId = e.tool_use_id
    const isTracked = !UNTRACKED.has(tool)
    if (isTracked) {
      await quietly(async () => {
        const input = e as Record<string, unknown>
        const at = await $.clock.now()
        push({ kind: 'toolStarted', agentId, tool, target: targetOf(tool, input), detail: detailOf(tool, input), callId, at })
        const counts = stationFor(tool) === 'taskboard' ? todoCounts(input) : null
        if (counts !== null) push({ kind: 'todos', ...counts, at })
      })
    }
    const ran = await next(e)
    if (isTracked) {
      await quietly(async () => {
        const isError = ran.deny === undefined && ran.isError === true
        push({ kind: 'toolEnded', agentId, callId, isError, at: await $.clock.now() })
      })
    }
    return ran
  }).catch(($, e, next) => next(e))

  on('agent.spawn', async ($, e, next) => {
    const spawned = await next(e)
    await quietly(async () => {
      if (spawned.deny !== undefined || spawned.agentId === undefined) return
      push({
        kind: 'spawned',
        id: spawned.agentId,
        parentId: e.parentAgentId ?? MAIN,
        type: e.subagentType,
        description: e.description,
        brief: fullText(e.prompt, TEXT_MAX),
        name: e.name ?? null,
        isTeammate: e.isTeammate === true,
        isBackground: e.background === true,
        isResume: e.resume !== undefined,
        at: await $.clock.now(),
      })
      if (autoOpen === 'on-first-subagent' && !office.isOpened) office.wantsOpen = true
    })
    return spawned
  }).catch(($, e, next) => next(e))

  // The engine settles a prompt before the main loop's turn starts; the turn reads where it came from.
  on('prompt.submit', async ($, e, next) => {
    office.lastOrigin = e.origin?.kind ?? null
    return next(e)
  }).catch(($, e, next) => next(e))

  on('turn.start', async ($, e, next) => {
    // The engine fires this for a helper's run too; only the main loop's turn is the person's message.
    if (e.agentId !== undefined) {
      if (office.isDebug) note('turn-ignored', { agent: e.agentId })
      return next(e)
    }
    const origin = office.lastOrigin
    office.lastOrigin = null
    const isNotice = origin !== null ? NOT_A_NEW_JOB.has(origin) : e.text.trimStart().startsWith('<task-notification')
    // A turn started without typed text, or woken by a notice, carries on the job under way.
    const continues = e.text === '' || isNotice
    if (office.isDebug) note('turn-start', { origin: origin ?? 'none', continues })
    await quietly(async () =>
      push({
        kind: 'turnStarted',
        isContinuation: continues,
        task: isNotice ? '' : gist(e.text, TASK_MAX),
        at: await $.clock.now(),
      }),
    )
    return next(e)
  }).catch(($, e, next) => next(e))

  on('turn.complete', async ($, e, next) => {
    await quietly(async () => {
      const at = await $.clock.now()
      const usage = usageOf(e.usage)
      if (e.agentId !== undefined) {
        push({ kind: 'handedBack', agentId: e.agentId, reason: e.reason, report: fullText(e.answer, TEXT_MAX), usage, at })
      } else push({ kind: 'turnEnded', usage, at })
    })
    return next(e)
  }).catch(($, e, next) => next(e))

  on('classic.PermissionRequest', async ($, e, next) => {
    await quietly(async () => {
      // A question or a plan approval already moved and narrated the agent when its tool call began.
      if (WAITING_TOOLS.has(e.tool_name)) return
      push({ kind: 'waiting', agentId: e.agent_id ?? null, tool: e.tool_name, at: await $.clock.now() })
    })
    return next(e)
  }).catch(($, e, next) => next(e))

  on('command.run', { command: 'office' }, async ($, e) => {
    // `/office settings` shows them, `/office set <name> <value>` changes one; `/office` alone shows or hides the pane.
    const [verb = '', ...rest] = e.args.trim().split(/\s+/)
    if (verb.toLowerCase() === 'settings') return { text: [...settingLines(options), SETTINGS_HELP].join('\n') }
    if (verb.toLowerCase() === 'set') {
      const request = parseSet(rest.join(' '))
      return { text: 'error' in request ? request.error : await changeSetting($, request.setting, request.value) }
    }
    if (verb !== '') return { text: USAGE }
    const panes = await $.ui.panes()
    if (panes.some(pane => pane.id === PANE)) {
      await $.ui.close({ id: PANE })
      return { text: 'Office closed.' }
    }
    await openPane($, office)
    return { text: 'Office opened.' }
  })

  // What this plugin's probes (a surface module inside the pane) post: only four plain fields are kept.
  on('ui.message', async ($, e, next) => {
    if (e.element !== PROBE_TOP && e.element !== PROBE_BOTTOM) return next(e)
    if (office.isDebug) {
      const d = typeof e.data === 'object' && e.data !== null ? (e.data as Record<string, unknown>) : {}
      note('probe', {
        element: e.element,
        ...(typeof d.kind === 'string' ? { msg: d.kind.slice(0, 32) } : {}), // not `kind`: that is the line's own
        ...(typeof d.where === 'string' ? { where: d.where.slice(0, 32) } : {}),
        ...(typeof d.columns === 'number' ? { columns: d.columns } : {}),
        ...(typeof d.rows === 'number' ? { rows: d.rows } : {}),
      })
    }
    return {}
  }).catch(($, e, next) => next(e))

  registerPane(on, { isDebug: office.isDebug, options })
}

files.hooks/debuglog.ts:
// An opt-in log of what the office does, kept in memory as JSON lines and written to a file by the flush.
// Off by default: every function below is a boolean check and nothing more until `debugOn(true)`.
export const LOG_MAX = 3000

let isOn = false
let lines: string[] = []
let isDirty = false

export function debugOn(enabled: boolean): void {
  isOn = enabled
}

// Values are plain numbers, booleans and short strings: agent ids, event kinds, tool names, never text of the work.
export function note(kind: string, data: Record<string, unknown> = {}, at?: number): void {
  if (!isOn) return
  lines.push(JSON.stringify({ t: at ?? Date.now(), kind, ...data }))
  if (lines.length > LOG_MAX) lines = lines.slice(lines.length - LOG_MAX)
  isDirty = true
}

export function logText(): string {
  return lines.length === 0 ? '' : `${lines.join('\n')}\n`
}

export function takeDirty(): boolean {
  const was = isDirty
  isDirty = false
  return was
}

export function clearLog(): void {
  lines = []
  isDirty = false
}

files.hooks/model.ts:
import type { Agent, Carry, OfficeEvent, Outcome, Point, Scene, StationId, Usage, Walk } from '../types'
import { allBackLine, narrate } from './narrate'
import { COORDINATOR, asName, roleFor } from './roles'
import { lookFor } from './sprites'
import {
  EXCERPT,
  WAITING_TOOLS,
  WIDTH,
  clamp,
  doorOf,
  fullText,
  pathLength,
  pointAlong,
  route,
  slotPoint,
  stationFor,
  toCorridor,
} from './stations'

export const MAIN = 'main'
export const TICKER_MAX = 8
export const GONE_KEEP = 50
export const FULL_KEEP = 10
export const LINGER_MS = 8_000
export const IDLE_MS = 600_000
export const BRIEFING_MAX_MS = 60_000
export const WALK_SPEED = 70

type Ev<K extends OfficeEvent['kind']> = Extract<OfficeEvent, { kind: K }>
type Stop = { point: Point; door: Point }

export function emptyScene(): Scene {
  const main: Agent = {
    id: MAIN,
    parentId: null,
    type: 'main',
    role: COORDINATOR.title,
    name: null,
    label: 'Main',
    description: '',
    brief: '',
    report: '',
    outcome: null,
    usage: null,
    isTeammate: false,
    isBackground: false,
    phase: 'idle',
    station: 'office',
    slot: 0,
    desk: -1,
    pos: slotPoint('office', 0),
    walk: null,
    activity: null,
    lastErrorAt: null,
    lastEventAt: 0,
    arrivedAt: 0,
    doneAt: null,
    goneAt: null,
    carry: null,
    look: lookFor('main', MAIN),
  }
  return { agents: { [MAIN]: main }, order: [MAIN], ticker: [], todos: null, briefing: null, job: null }
}

// Fields added to an agent since the first release, with what an agent saved without them stands for. Session
// state outlives a hot reload of the mod, so a scene saved by an older version can meet this code.
const AGENT_DEFAULTS = (agent: Agent): Partial<Agent> => ({
  role: roleFor(agent.type).title,
  name: null,
  brief: '',
  report: '',
  outcome: null,
  // Nothing says its boss waits on it, so it never makes its boss look busy.
  isBackground: true,
  carry: null,
  usage: null,
  doneAt: null,
})
const AGENT_KEYS = Object.keys(AGENT_DEFAULTS({ type: MAIN } as Agent)) as (keyof Agent)[]

// The scene as this version reads it. The same object comes back when nothing is missing, so a scene that is
// already whole is never rewritten (a write would redraw the pane).
export function restore(scene: Scene): Scene {
  const isWhole = (agent: Agent): boolean => AGENT_KEYS.every(key => key in agent)
  const hasJob = 'job' in scene
  if (hasJob && Object.values(scene.agents).every(isWhole)) return scene
  const agents: Record<string, Agent> = {}
  for (const [id, agent] of Object.entries(scene.agents)) {
    agents[id] = isWhole(agent) ? agent : ({ ...AGENT_DEFAULTS(agent), ...agent } as Agent)
  }
  return { ...scene, agents, job: hasJob ? scene.job : null }
}

export function isWalkingAt(agent: Agent, at: number): boolean {
  return agent.walk !== null && at < agent.walk.startedAt + agent.walk.durationMs
}

export function positionAt(agent: Agent, at: number): Point {
  if (agent.walk === null || !isWalkingAt(agent, at)) return agent.pos
  return pointAlong(agent.walk.points, (at - agent.walk.startedAt) / agent.walk.durationMs)
}

export function homeOf(agent: Agent): StationId {
  return agent.desk < 0 ? 'office' : 'desk'
}

const put = (scene: Scene, agent: Agent): Scene => ({ ...scene, agents: { ...scene.agents, [agent.id]: agent } })

const addAgent = (scene: Scene, agent: Agent): Scene => ({ ...put(scene, agent), order: [...scene.order, agent.id] })

// A routine line replaces the same agent's last routine line, so a few busy helpers cannot push the story
// (who hired whom, who reported back, who needs you) out of the feed within seconds.
function withLine(scene: Scene, at: number, text: string | null, routineOf: string | null = null): Scene {
  if (text === null) return scene
  const kept = routineOf === null ? scene.ticker : scene.ticker.filter(line => line.routineOf !== routineOf)
  return { ...scene, ticker: [...kept, { at, text, routineOf }].slice(-TICKER_MAX) }
}

// Tool calls that are part of the story rather than routine work: a message to another agent, and a wait on you.
const isMilestone = (tool: string): boolean => tool === 'SendMessage' || WAITING_TOOLS.has(tool)

function freeSlot(scene: Scene, station: StationId, selfId: string): number {
  const taken = new Set(
    Object.values(scene.agents)
      .filter(a => a.id !== selfId && a.phase !== 'gone' && a.station === station)
      .map(a => a.slot),
  )
  let slot = 0
  while (taken.has(slot)) slot += 1
  return slot
}

const walkMs = (length: number): number => clamp(Math.round((length / WALK_SPEED) * 1000), 700, 7000)

const isNear = (a: Point, b: Point): boolean => Math.hypot(a.x - b.x, a.y - b.y) < 0.5

// Every walk drops whatever the agent was carrying, unless `item` says it carries something this time: it is
// handed over when the walk reaches the first stop in `via`, the agent it is walking to.
function moveTo(
  scene: Scene,
  agent: Agent,
  target: StationId,
  at: number,
  via: readonly Stop[] = [],
  item: Carry['item'] | null = null,
): Agent {
  const station: StationId = target === 'desk' && agent.desk < 0 ? 'office' : target
  if (via.length === 0 && station === agent.station) return agent
  const slot =
    station === agent.station
      ? agent.slot
      : station === 'desk'
        ? agent.desk
        : station === 'office'
          ? 0
          : freeSlot(scene, station, agent.id)
  const dest = slotPoint(station, slot)
  const current = agent.walk !== null && isWalkingAt(agent, at) ? agent.walk : null
  // Sent back to where it stood before its walk began, it never left.
  if (current !== null && via.length === 0 && at <= current.startedAt && isNear(current.points[0] as Point, dest)) {
    return { ...agent, station, slot, pos: dest, walk: null, carry: null }
  }
  // A walk that changes course first gets back to the corridor along the path it is on.
  const rejoin = current === null ? [] : toCorridor(current.points, (at - current.startedAt) / current.durationMs)
  const lead = rejoin.length > 0 ? rejoin : [positionAt(agent, at)]
  const start = lead[lead.length - 1] as Point
  const stops: Stop[] = [
    { point: start, door: current !== null ? start : doorOf(agent.station, agent.slot) },
    ...via,
    { point: dest, door: doorOf(station, slot) },
  ]
  let points: Point[] = lead
  let handover = 0
  for (let i = 1; i < stops.length; i++) {
    const a = stops[i - 1] as Stop
    const b = stops[i] as Stop
    points = points.concat(route(a.point, a.door, b.point, b.door).slice(1))
    if (i === 1) handover = pathLength(points)
  }
  const length = pathLength(points)
  const walk: Walk | null = length < 0.5 ? null : { points, startedAt: at, durationMs: walkMs(length) }
  const carry: Carry | null =
    item === null || walk === null || via.length === 0
      ? null
      : { item, until: at + Math.round((walk.durationMs * handover) / length) }
  return { ...agent, station, slot, pos: dest, walk, carry }
}

function beside(agent: Agent): Stop {
  return {
    point: { x: clamp(agent.pos.x + 9, 4, WIDTH - 4), y: agent.pos.y },
    door: doorOf(agent.station, agent.slot),
  }
}

// The first of a kind is plain "Researcher", the next "Researcher 2". Numbering goes on from the highest number
// in the office, so a label is never handed out twice, even after old helpers are pruned from the model.
function uniqueLabel(scene: Scene, base: string): string {
  let highest = 0
  for (const a of Object.values(scene.agents)) {
    if (a.label === base) highest = Math.max(highest, 1)
    else if (a.label.startsWith(`${base} `)) {
      const n = Number(a.label.slice(base.length + 1))
      if (Number.isInteger(n) && n > 1) highest = Math.max(highest, n)
    }
  }
  return highest === 0 ? base : `${base} ${highest + 1}`
}

// What a helper is on the job for, in a few words: "Find the login code" reads as "login code". Short enough to
// fit on a name tag.
const TOPIC_MAX = 12
const FILLER = /^(find|check|look|search|read|review|audit|investigate|explore|analy[sz]e|summari[sz]e|report|list|get|the|a|an|for|on|in|at|of|into|out|how|why|what|where|which|whether|if|and|to)$/i
export function topicOf(description: string): string {
  const words = description.split(/\s+/).filter(w => w !== '')
  const keep = words.filter(w => !FILLER.test(w.replace(/[^A-Za-z]/g, '')))
  const pool = (keep.length > 0 ? keep : words).map(w => w.toLowerCase())
  // Whole words only: two if they fit, else the first, cut with an ellipsis if even that is too long.
  const two = pool.slice(0, 2).join(' ')
  if (Array.from(two).length <= TOPIC_MAX) return two
  const first = pool[0] ?? ''
  const chars = Array.from(first)
  return chars.length <= TOPIC_MAX ? first : `${chars.slice(0, TOPIC_MAX - 1).join('')}…`
}

// An agent the engine named keeps its name. The first of a kind is its plain job title; a later one is told apart
// by its job, "Hooks module" rather than "Researcher 2", when we know it. The job alone is the name: a tag has
// room for about twelve characters before it runs into its neighbour's, and the details say what kind of agent it is.
const labelFor = (scene: Scene, type: string, name: string | null, description = ''): string => {
  if (name !== null && name !== '') return uniqueLabel(scene, asName(name))
  const topic = topicOf(description)
  const title = roleFor(type).title
  const first = uniqueLabel(scene, title)
  if (first === title || topic === '') return first
  return uniqueLabel(scene, `${topic[0]?.toUpperCase() ?? ''}${topic.slice(1)}`)
}

function nextDesk(scene: Scene): number {
  const used = new Set(
    Object.values(scene.agents)
      .filter(a => a.phase !== 'gone' && a.desk >= 0)
      .map(a => a.desk),
  )
  let desk = 0
  while (used.has(desk)) desk += 1
  return desk
}

// A contractor (an agent the office never saw hired) is taken to work in the background: nothing says its boss
// is waiting on it, so it never makes its boss look busy.
function arrive(scene: Scene, id: string, type: string, label: string, at: number): Agent {
  return {
    id,
    parentId: MAIN,
    type,
    role: roleFor(type).title,
    name: null,
    label,
    description: '',
    brief: '',
    report: '',
    outcome: null,
    usage: null,
    isTeammate: false,
    isBackground: true,
    phase: 'arriving',
    station: 'elevator',
    slot: 0,
    desk: nextDesk(scene),
    pos: slotPoint('elevator', 0),
    walk: null,
    activity: null,
    lastErrorAt: null,
    lastEventAt: at,
    arrivedAt: at,
    doneAt: null,
    goneAt: null,
    carry: null,
    look: lookFor(type, id),
  }
}

const isOut = (agent: Agent): boolean =>
  agent.phase === 'arriving' || agent.phase === 'briefing' || agent.phase === 'working' || agent.phase === 'waiting'

// The helpers `bossId` is waiting on: hired in the foreground (the boss's call to hire them only returns with
// their report) and still out on the job, in the order they were hired. A teammate is a standing colleague
// rather than an errand, so its boss never waits on it.
export function waitingOn(scene: Scene, bossId: string): Agent[] {
  const out: Agent[] = []
  for (const id of scene.order) {
    const a = scene.agents[id]
    if (a !== undefined && a.parentId === bossId && !a.isBackground && !a.isTeammate && isOut(a)) out.push(a)
  }
  return out
}

// A boss with nothing in hand, waiting for the reports of the helpers it hired, is coordinating rather than
// thinking. A boss that is using a tool, waiting on you, resting or gone is doing that instead.
export function isCoordinating(scene: Scene, agent: Agent): boolean {
  if (agent.activity !== null || agent.phase === 'gone' || agent.phase === 'idle' || agent.phase === 'waiting') return false
  return waitingOn(scene, agent.id).length > 0
}

function endBriefing(scene: Scene, agent: Agent, at: number, t: number): Scene {
  const stillBriefing = Object.values(scene.agents).some(a => a.phase === 'briefing')
  let out: Scene = stillBriefing ? scene : { ...scene, briefing: null }
  const parent = agent.parentId === null ? undefined : out.agents[agent.parentId]
  if (parent !== undefined && parent.station === 'meeting' && parent.activity === null && parent.phase !== 'gone') {
    out = put(out, { ...moveTo(out, parent, homeOf(parent), t), lastEventAt: at })
  }
  return out
}

// The agent walks to the meeting room to be briefed, its boss joins it there unless busy, and the whiteboard
// shows the job.
function brief(scene: Scene, agent: Agent, ev: Ev<'spawned'>, t: number): Scene {
  let s = put(scene, { ...moveTo(scene, agent, 'meeting', t), phase: 'briefing' })
  const parent = s.agents[ev.parentId]
  if (parent !== undefined && parent.activity === null && parent.phase !== 'gone') {
    s = put(s, { ...moveTo(s, parent, 'meeting', t), phase: 'working', lastEventAt: ev.at })
  }
  return { ...s, briefing: ev.description }
}

// A helper back for more work after it handed in its report. One still on its way out turns round where it is;
// one that has ridden away steps out of the elevator again.
function comeBack(scene: Scene, agent: Agent, t: number): Partial<Agent> {
  const hasLeft = agent.goneAt === null || t >= agent.goneAt
  return { ...(hasLeft ? { station: 'elevator' as const, slot: 0, pos: slotPoint('elevator', 0), walk: null } : {}), desk: nextDesk(scene) }
}

// A called-back agent comes back if it had left, starts a new stint and is briefed again. The message it is
// called back with is its new brief; with none, the old brief still stands.
function callBack(scene: Scene, agent: Agent, ev: Ev<'spawned'>, t: number): Scene {
  const isBack = agent.phase === 'gone'
  const returning: Agent = {
    ...agent,
    ...(isBack ? comeBack(scene, agent, t) : {}),
    parentId: ev.parentId,
    description: ev.description,
    brief: ev.brief === '' ? agent.brief : ev.brief,
    isBackground: ev.isBackground,
    outcome: null,
    doneAt: null,
    goneAt: null,
    carry: null,
    activity: null,
    arrivedAt: ev.at,
    lastEventAt: ev.at,
  }
  return brief(scene, returning, ev, t)
}

function spawned(scene: Scene, ev: Ev<'spawned'>, t: number): Scene {
  const existing = scene.agents[ev.id]
  let s = scene
  const hire = {
    parentId: ev.parentId,
    description: ev.description,
    brief: ev.brief,
    name: ev.name,
    isTeammate: ev.isTeammate,
    isBackground: ev.isBackground,
  }
  if (existing === undefined) {
    const fresh = { ...arrive(s, ev.id, ev.type, labelFor(s, ev.type, ev.name, ev.description), ev.at), ...hire }
    s = brief(addAgent(s, fresh), fresh, ev, t)
  } else if (ev.isResume) {
    s = callBack(s, existing, ev, t)
  } else {
    const label = existing.type === 'contractor' ? labelFor(s, ev.type, ev.name, ev.description) : existing.label
    s = put(s, {
      ...existing,
      ...hire,
      type: ev.type,
      role: roleFor(ev.type).title,
      label,
      look: lookFor(ev.type, ev.id),
      lastEventAt: ev.at,
    })
  }
  return withLine(s, ev.at, narrate(s, ev))
}

// Messages are addressed by the name the engine knows an agent by, by its id, or (for "main") by its label.
function findByName(scene: Scene, name: string, selfId: string): Agent | undefined {
  const wanted = name.toLowerCase()
  return Object.values(scene.agents).find(
    a =>
      a.id !== selfId &&
      a.phase !== 'gone' &&
      (a.name?.toLowerCase() === wanted || a.label.toLowerCase() === wanted || a.id === name),
  )
}

const EDITING: ReadonlySet<string> = new Set(['Edit', 'Write', 'NotebookEdit'])

function toolStarted(scene: Scene, ev: Ev<'toolStarted'>, t: number): Scene {
  let s = scene
  let agent = s.agents[ev.agentId]
  if (agent === undefined) {
    agent = arrive(s, ev.agentId, 'contractor', uniqueLabel(s, 'Contractor'), ev.at)
    s = addAgent(s, agent)
  } else if (agent.phase === 'gone') {
    agent = {
      ...agent,
      ...comeBack(s, agent, t),
      phase: 'arriving',
      goneAt: null,
      doneAt: null,
      outcome: null,
      carry: null,
      arrivedAt: ev.at,
    }
  }
  const wasBriefing = agent.phase === 'briefing'
  let moved: Agent
  if (ev.tool === 'SendMessage') {
    const recipient = findByName(s, ev.target, agent.id)
    moved =
      recipient !== undefined
        ? moveTo(s, agent, agent.station, t, [beside(recipient)], 'message')
        : moveTo(s, agent, 'meeting', t)
  } else {
    moved = moveTo(s, agent, stationFor(ev.tool), t)
  }
  s = put(s, {
    ...moved,
    phase: WAITING_TOOLS.has(ev.tool) ? 'waiting' : 'working',
    activity: { tool: ev.tool, target: ev.target, detail: ev.detail, callId: ev.callId, since: ev.at },
    lastEventAt: ev.at,
  })
  if (wasBriefing) s = endBriefing(s, agent, ev.at, t)
  // The coordinator is meant to hire helpers for edits; the recap says how many it made itself.
  if (agent.id === MAIN && EDITING.has(ev.tool) && s.job !== null) s = { ...s, job: { ...s.job, mainEdits: (s.job.mainEdits ?? 0) + 1 } }
  return withLine(s, ev.at, narrate(s, ev), isMilestone(ev.tool) ? null : agent.id)
}

function toolEnded(scene: Scene, ev: Ev<'toolEnded'>, t: number): Scene {
  const agent = scene.agents[ev.agentId]
  if (agent === undefined || agent.phase === 'gone') return scene
  const isCurrent = agent.activity?.callId === ev.callId
  let next: Agent = {
    ...agent,
    activity: isCurrent ? null : agent.activity,
    lastErrorAt: ev.isError ? ev.at : agent.lastErrorAt,
    lastEventAt: ev.at,
  }
  if (isCurrent && agent.phase === 'waiting') next = { ...moveTo(scene, next, homeOf(next), t), phase: 'working' }
  return withLine(put(scene, next), ev.at, narrate(scene, ev))
}

function latestUser(scene: Scene, tool: string): string {
  let best: Agent | undefined
  for (const a of Object.values(scene.agents)) {
    if (a.phase === 'gone' || a.activity?.tool !== tool) continue
    if (best === undefined || a.activity.since > (best.activity?.since ?? -1)) best = a
  }
  return best?.id ?? MAIN
}

function waiting(scene: Scene, ev: Ev<'waiting'>, t: number): Scene {
  const id = ev.agentId !== null && scene.agents[ev.agentId] !== undefined ? ev.agentId : latestUser(scene, ev.tool)
  const agent = scene.agents[id]
  if (agent === undefined || agent.phase === 'gone') return scene
  const s = put(scene, { ...moveTo(scene, agent, 'reception', t), phase: 'waiting', lastEventAt: ev.at })
  return withLine(s, ev.at, narrate(s, { ...ev, agentId: id }))
}

// A message from you starts a new job; a turn that carries on without one reopens the job it belongs to.
function turnStarted(scene: Scene, ev: Ev<'turnStarted'>, t: number): Scene {
  const main = scene.agents[MAIN]
  if (main === undefined) return scene
  const job =
    ev.isContinuation && scene.job !== null
      ? { ...scene.job, endedAt: null }
      : { startedAt: ev.at, endedAt: null, task: ev.task, mainUsage: null, mainEdits: 0 }
  const s = put({ ...scene, job }, { ...moveTo(scene, main, 'office', t), phase: 'working', lastEventAt: ev.at })
  return withLine(s, ev.at, narrate(s, ev))
}

// Main's turn is over: it rests where it stands until the next message. No walk; the sweep takes it
// home after a short while and to the break room after a long one.
// A teammate or a called-back helper works more than one turn, and Main works one per message: their costs add up.
export function addUsage(sum: Usage | null, more: Usage | null): Usage | null {
  if (more === null) return sum
  if (sum === null) return more
  return { tokens: sum.tokens + more.tokens, reused: sum.reused + more.reused, model: more.model }
}

function turnEnded(scene: Scene, ev: Ev<'turnEnded'>): Scene {
  const main = scene.agents[MAIN]
  if (main === undefined) return scene
  const job = scene.job === null ? null : { ...scene.job, endedAt: ev.at, mainUsage: addUsage(scene.job.mainUsage, ev.usage) }
  const s = put({ ...scene, job }, { ...main, phase: 'idle', activity: null, usage: addUsage(main.usage, ev.usage), lastEventAt: ev.at })
  return withLine(s, ev.at, narrate(s, ev))
}

function prune(scene: Scene): Scene {
  const gone = scene.order.filter(id => scene.agents[id]?.phase === 'gone')
  if (gone.length <= GONE_KEEP) return scene
  const drop = new Set(gone.slice(0, gone.length - GONE_KEEP))
  const agents = { ...scene.agents }
  for (const id of drop) delete agents[id]
  return { ...scene, agents, order: scene.order.filter(id => !drop.has(id)) }
}

// Only the most recently finished helpers keep their whole brief and report; older ones keep as much as the
// one-line excerpt shows. That bounds the scene, which is written to state on every change.
function trimTexts(scene: Scene): Scene {
  const isLong = (a: Agent): boolean => a.brief.length > EXCERPT || a.report.length > EXCERPT
  const old = Object.values(scene.agents)
    .filter(a => a.phase === 'gone')
    .sort((a, b) => (b.goneAt ?? 0) - (a.goneAt ?? 0))
    .slice(FULL_KEEP)
    .filter(isLong)
  if (old.length === 0) return scene
  const agents = { ...scene.agents }
  for (const a of old) agents[a.id] = { ...a, brief: fullText(a.brief, EXCERPT), report: fullText(a.report, EXCERPT) }
  return { ...scene, agents }
}

const OUTCOMES: Readonly<Record<Ev<'handedBack'>['reason'], Outcome>> = {
  answer: 'reported',
  aborted: 'stopped',
  refusal: 'failed',
  error: 'failed',
}

// The helper carries its report to its boss, then leaves by the elevator (a teammate goes for a break instead).
// When it was the last report its boss was waiting for, the feed says so: that is when the boss takes over again.
function handedBack(scene: Scene, ev: Ev<'handedBack'>, t: number): Scene {
  const agent = scene.agents[ev.agentId]
  if (agent === undefined || agent.id === MAIN || agent.phase === 'gone') return scene
  const parent = agent.parentId === null ? undefined : scene.agents[agent.parentId]
  const isParentHere = parent !== undefined && parent.phase !== 'gone'
  const via = isParentHere ? [beside(parent)] : []
  const outcome = OUTCOMES[ev.reason]
  const item = outcome === 'stopped' ? null : 'report'
  let next: Agent
  if (agent.isTeammate) {
    next = { ...moveTo(scene, agent, 'breakroom', t, via, item), phase: 'idle' }
  } else {
    const moved = moveTo(scene, agent, 'elevator', t, via, item)
    next = { ...moved, phase: 'gone', goneAt: t + (moved.walk?.durationMs ?? 0) }
  }
  const awaitedBy = isParentHere && waitingOn(scene, parent.id).some(a => a.id === agent.id) ? parent : undefined
  let s = put(scene, {
    ...next,
    activity: null,
    report: ev.report,
    outcome,
    usage: addUsage(agent.usage, ev.usage),
    doneAt: ev.at,
    lastEventAt: ev.at,
  })
  if (agent.phase === 'briefing') s = endBriefing(s, agent, ev.at, t)
  s = trimTexts(prune(s))
  s = withLine(s, ev.at, narrate(s, ev))
  if (awaitedBy !== undefined && waitingOn(s, awaitedBy.id).length === 0) s = withLine(s, ev.at, allBackLine(awaitedBy.label))
  return s
}

// A boss waiting on its helpers is at work however long they take, so the sweep may walk it home but never
// sends it to the break room.
function sweepTarget(agent: Agent, now: number, isWaitingOnTeam: boolean): StationId | null {
  // An agent waiting on you stays at reception until you answer, however long that takes.
  if (agent.activity !== null || agent.phase === 'gone' || agent.phase === 'waiting') return null
  const quiet = now - agent.lastEventAt
  // A briefing normally ends with the agent's first tool; one that never comes must not hold the room forever.
  if (agent.phase === 'briefing') return quiet >= BRIEFING_MAX_MS ? homeOf(agent) : null
  if (agent.phase === 'idle') {
    // Resting in the break room is the end of the road, and an office where nothing has happened yet
    // (Main's clock still reads zero) has nobody to send for coffee.
    if (agent.station === 'breakroom' || agent.lastEventAt === 0) return null
    if (quiet >= IDLE_MS) return 'breakroom'
    return quiet >= LINGER_MS && agent.station !== homeOf(agent) ? homeOf(agent) : null
  }
  if (quiet >= IDLE_MS && !isWaitingOnTeam) return 'breakroom'
  if (quiet >= LINGER_MS && agent.station !== homeOf(agent)) return homeOf(agent)
  return null
}

export function needsSweep(scene: Scene, now: number): boolean {
  return Object.values(scene.agents).some(a => sweepTarget(a, now, isCoordinating(scene, a)) !== null)
}

function tick(scene: Scene, at: number, t: number): Scene {
  let s = scene
  for (const id of scene.order) {
    const agent = s.agents[id]
    if (agent === undefined) continue
    const target = sweepTarget(agent, at, isCoordinating(s, agent))
    if (target === null) continue
    s = put(s, { ...moveTo(s, agent, target, t), phase: target === 'breakroom' || agent.phase === 'idle' ? 'idle' : 'working' })
    if (agent.phase === 'briefing') s = endBriefing(s, agent, at, t)
  }
  return s
}

export function reduce(scene: Scene, ev: OfficeEvent): Scene {
  return reduceAt(scene, ev, ev.at)
}

// The event as the picture plays it: `shownAt` is the first moment the picture can show it, and the walks it
// starts begin then rather than at the event's own time. Begun at the event's time, a walk would already be part
// way along when it first appeared (the wait for the next flush, and the time the picture takes to appear), so the
// walker would leap ahead at the start of every walk. What the office reports (the feed, the recap, the clocks)
// keeps the event's own time.
export function reduceAt(scene: Scene, ev: OfficeEvent, shownAt: number): Scene {
  const t = Math.max(ev.at, shownAt)
  switch (ev.kind) {
    case 'spawned':
      return spawned(scene, ev, t)
    case 'toolStarted':
      return toolStarted(scene, ev, t)
    case 'toolEnded':
      return toolEnded(scene, ev, t)
    case 'waiting':
      return waiting(scene, ev, t)
    case 'turnStarted':
      return turnStarted(scene, ev, t)
    case 'turnEnded':
      return turnEnded(scene, ev)
    case 'handedBack':
      return handedBack(scene, ev, t)
    case 'todos':
      return { ...scene, todos: { done: ev.done, open: ev.open } }
    case 'tick':
      return tick(scene, ev.at, t)
  }
}

